'use client';

import { IconPlaceholder } from '@/components/icon-placeholder';
import { ElementApi } from 'platejs';
import {
  IndentPlugin,
  ListPlugin,
  useEditor,
  useEditorReadOnly,
} from 'platejs/react';
import * as React from 'react';

import { ToolbarButton } from '@/registry/components/editor/toolbar';

export function IndentToolbarButton(
  props: React.ComponentProps<typeof ToolbarButton>
) {
  const editor = useEditor();
  const readOnly = useEditorReadOnly();

  return (
    <ToolbarButton
      {...props}
      disabled={props.disabled || readOnly}
      tooltip="Indent"
      onClick={() => {
        editor.plugin(IndentPlugin).update.increase();
        editor.api.dom.focus();
      }}
    >
      <IconPlaceholder lucide="IndentIcon" tabler="IconIndentIncrease" hugeicons="TextIndentMoreIcon" phosphor="TextIndentIcon" remixicon="RiIndentIncrease" className="[&:dir(rtl)]:-scale-x-100" />
    </ToolbarButton>
  );
}

export function OutdentToolbarButton(
  props: React.ComponentProps<typeof ToolbarButton>
) {
  const editor = useEditor();
  const readOnly = useEditorReadOnly();

  return (
    <ToolbarButton
      {...props}
      disabled={props.disabled || readOnly}
      tooltip="Outdent"
      onClick={() => {
        const list = editor.plugin(ListPlugin);

        if (
          list.installed &&
          editor.read.nodes.some({
            match: (node) => ElementApi.isElement(node) && !!node.listType,
          })
        ) {
          list.update.outdent();
        } else {
          editor.plugin(IndentPlugin).update.decrease();
        }
        editor.api.dom.focus();
      }}
    >
      <IconPlaceholder lucide="OutdentIcon" tabler="IconIndentDecrease" hugeicons="TextIndentLessIcon" phosphor="TextOutdentIcon" remixicon="RiIndentDecrease" className="[&:dir(rtl)]:-scale-x-100" />
    </ToolbarButton>
  );
}
